fn add(mut d:RetirementDemand,bytes:usize)->Result<RetirementDemand,ValueError>{d.copy_bytes=d.copy_bytes.checked_add(bytes).ok_or_else(invalid)?;Ok(d)}
fn posted(mut p:RetainedCloneProgress,bytes:usize,work:u64)->Result<RetainedCloneProgress,ValueError>{if work!=0{p.copied_items=p.copied_items.max(1);p.copied_bytes=p.copied_bytes.checked_add(bytes).ok_or_else(invalid)?;}Ok(p)}
