 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<DslValue>(false,&None,body)}if let Some(admission)=self.admission.as_ref(){return admission.next_return_demand()}if let Some(receiver)=self.receiver.as_ref(){return if receiver.terminal_is_empty(){Ok(fixed(size_of::<Option<NativeReceivingOriginal<DslValue,T>>>()))}else{receiver.close_demands(body)}}if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(fixed(size_of::<Option<RetainedCloneSource<DslValue>>>()))}else{source.next_close_demand(body)}}macro_rules! owner{($field:ident,$ty:ty)=>{if self.$field.is_some(){return self.retirement.next_owner_demands::<$ty>(true,&None,body)}};}owner!(parser,JsonGrammarCursor<DslValue>);owner!(parsed,DslValue);owner!(output,T);owner!(syntax,JsonError);Ok(Default::default())}
 pub fn close_step(&mut self,control:&mut dyn OriginalRetirementControl,g:RetainedCloneGrant)->RetainedWorkOutcome{let g=RetainedCloneGrant{maximum_items:g.maximum_items.min(1),..g};let mut work=0;let result=(||{if self.ledger!=control.ledger_identity()||self.recipient!=control.retirement_recipient_identity()||!self.closing{return Err(invalid())}if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if d.capacity_bytes!=0{control.charge(d.capacity_bytes)?}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(g);work=turn.work;return turn.result}if let Some(admission)=self.admission.as_mut(){let mut returned=None;let turn=admission.return_inputs(&mut returned,g);work=turn.work;if let Some((value,()))=returned{*self.parsed=Some(value)}if admission.terminal_is_empty(){self.admission.take();}return turn.result}if let Some(receiver)=self.receiver.as_mut(){if receiver.terminal_is_empty(){self.receiver.take();work=1;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}let turn=receiver.close_step(g);work=turn.work;return turn.result}if let Some(source)=self.source.as_mut(){if source.terminal_is_empty(){self.source.take();work=1;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}let turn=source.close_step(g);work=turn.work;return turn.result}macro_rules! close{($field:ident)=>{if self.$field.is_some(){let turn=self.retirement.begin_granted(&mut self.$field,g);work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default())))}};}close!(parser);close!(parsed);close!(output);close!(syntax);Ok(RetainedCloneStep::Complete(Default::default()))})();RetainedWorkOutcome{result,work}}
